#include "ouroboros_sim.h"
#include "om_internal.h"
#include "om_constants.h"
#include <math.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

/* B11 (E-12): per-world fog state lives in w->fog_state / w->fog_state_free,
 * mirroring csrc/unit.c's om_tac/om_tac_ro (tactical_state) convention and
 * csrc/mission.c's om_mis/om_mis_ro (mission_state) convention exactly.
 * Unit facts (faction, type, alive, position) come from unit.c's public
 * accessors; the only unit fact fog.c stores itself is the elevation tier,
 * because no accessor exposes it. */

#define OM_FOG_MAX_ZONES 64
#define OM_FOG_MAX_VANTAGE 32
#define OM_FOG_MAX_TRACKED_UNITS OM_MAX_UNITS
#define OM_FOG_MAX_ERA_FLAGS 16
#define OM_FOG_ERA_NAME_LEN 64
#define OM_FOG_ERA_FLAG_NAME_LEN 64

#define OM_FOG_PHASE_RECON 0
#define OM_FOG_PHASE_TACTICAL 1

#define OM_FOG_TREATMENT_REVEALED 0
#define OM_FOG_TREATMENT_FOGGED 1
#define OM_FOG_TREATMENT_INTERFERENCE 2

/* HDR3 legacy fallback: worlds with no configured player faction still reveal
 * fog to faction 0 in tile queries and the snapshot builder. */
#define OM_FOG_PLAYER_FACTION_FALLBACK 0

/* HDR3 rule 2: use configured player faction when available, else fallback 0. */
static int32_t fog_player_faction_id(const om_world *w) {
    int32_t pf = om_player_faction(w);
    return pf >= 0 ? pf : OM_FOG_PLAYER_FACTION_FALLBACK;
}

typedef struct {
    double x, y;
    uint32_t layer;
    double intensity;
    double radius;
    int moving;
    double vx, vy;
    uint64_t start_tick;
} om_fog_zone;

typedef struct {
    double x, y;
    double radius;
} om_fog_vantage;

typedef struct {
    uint32_t unit_id;
    int elevation_tier;
} om_fog_unit_track;

/* G7: a cast ping, live for OM_TP_PING_REVEAL_TICKS tactical ticks after the cast. R-162-01: it holds the units
 * caught inside its disc at the cast as a bitset over unit ids (ids are dense and never reused in a battle, unit.c),
 * so there is no overflow case. */
#define OM_FOG_BITS_PER_WORD 64u
#define OM_FOG_CAUGHT_WORDS ((OM_MAX_UNITS + OM_FOG_BITS_PER_WORD) / OM_FOG_BITS_PER_WORD)
#define OM_FOG_MAX_REVEALS 64
#define OM_FOG_MAX_ALERTS 256
#define OM_FOG_PING_EDGE_SLOPE_SQ 3.0 /* the 60 and 120 degree edges have slope sqrt(3) */
/* om_command_ping refusal reasons (docs/northstar/plans/push/pp_contract.md section 6) */
#define OM_FOG_PING_REASON_CASTER 1
#define OM_FOG_PING_REASON_REACH 2
#define OM_FOG_PING_REASON_COOLDOWN 3
#define OM_FOG_PING_REASON_LAYER 4
#define OM_FOG_PING_REASON_GROUND 5 /* terrain stage 2: ping is space-only */
#define OM_FOG_PING_DOWN_SECTORS 3
#define OM_FOG_MAX_PINGED_FACTIONS 16
typedef struct {
    int32_t faction;
    uint32_t layer;
    double x, y, radius;
    uint64_t until;
    uint64_t caught[OM_FOG_CAUGHT_WORDS];
} om_fog_ping_reveal;

typedef struct {
    char name[OM_FOG_ERA_FLAG_NAME_LEN];
    int on;
} om_fog_era_flag;

typedef struct {
    om_fog_zone zones[OM_FOG_MAX_ZONES];
    uint32_t n_zones;

    om_fog_vantage vantage[OM_FOG_MAX_VANTAGE];
    uint32_t n_vantage;

    uint32_t next_feature_id;

    om_fog_unit_track units[OM_FOG_MAX_TRACKED_UNITS];
    uint32_t n_units;

    om_fog_era_flag era_flags[OM_FOG_MAX_ERA_FLAGS];
    uint32_t n_era_flags;
    char era_name[OM_FOG_ERA_NAME_LEN];
    int era_kind; /* terrain stage 2: 0 space (default), 1 ground; see om_set_era_kind */

    int mission_phase;
    int mission_started;
    uint64_t mission_begin_base_tick;

    int player_fog_on;
    int player_fog_on_set;

    uint32_t bound_scanned;
    double max_sensor;
    int max_elev;

    uint8_t emit[OM_MAX_UNITS + 1];

    uint64_t ping_cast_plus1[OM_MAX_UNITS + 1];
    om_fog_ping_reveal reveals[OM_FOG_MAX_REVEALS];
    uint32_t n_reveals;
    om_ping_alert alerts[OM_FOG_MAX_ALERTS];
    uint32_t n_alerts;

    om_client_snapshot snapshot;
} om_fog_state;

static uint32_t om_fog_state_size_hook(const om_world *w);
static void om_fog_state_write_hook(const om_world *w, uint8_t *out);
static int om_fog_state_read_hook(om_world *w, const uint8_t *buf, uint32_t len);

static void om_fog_state_free_fn(void *p) {
    free(p);
}

static om_fog_state *om_fog(om_world *w) {
    om_fog_state *st = (om_fog_state *)w->fog_state;
    if (!st) {
        st = (om_fog_state *)calloc(1, sizeof(om_fog_state));
        st->player_fog_on = 1;
        st->mission_phase = -1;
        w->fog_state = st;
        w->fog_state_free = om_fog_state_free_fn;
        w->fog_state_size = om_fog_state_size_hook;
        w->fog_state_write = om_fog_state_write_hook;
        w->fog_state_read = om_fog_state_read_hook;
    }
    return st;
}

static const om_fog_state *om_fog_ro(const om_world *w) {
    return (const om_fog_state *)w->fog_state;
}

static double om_fog_clamp01(double v) {
    if (v < 0.0) return 0.0;
    if (v > 1.0) return 1.0;
    return v;
}

static double om_fog_dist(double x1, double y1, double x2, double y2) {
    double dx = x2 - x1, dy = y2 - y1;
    return sqrt(dx * dx + dy * dy);
}

/* F7 (R-087-10): sensor radius is measured spherically, the horizontal distance and the height difference of the two layers together. */
static double om_fog_slant(const om_world *w, double ox, double oy, uint32_t ol, double tx, double ty, uint32_t tl) {
    double dx = tx - ox, dy = ty - oy, dz = om_terrain_layer_dz(w, ol, tl);
    return sqrt(dx * dx + dy * dy + dz * dz);
}

static const om_fog_unit_track *om_fog_find_tracked(const om_fog_state *st, uint32_t unit_id) {
    uint32_t i;
    if (!st) return NULL;
    for (i = 0; i < st->n_units; i++) {
        if (st->units[i].unit_id == unit_id) return &st->units[i];
    }
    return NULL;
}

static int om_fog_in_vantage(const om_fog_state *st, double x, double y) {
    uint32_t i;
    if (!st || st->era_kind == 1) return 0;
    for (i = 0; i < st->n_vantage; i++) {
        if (om_fog_dist(x, y, st->vantage[i].x, st->vantage[i].y) <= st->vantage[i].radius) return 1;
    }
    return 0;
}

/* ALG-65 interference at (x, y, layer): sum of every zone's linear falloff
 * on that layer, clamped to [0, 1] (R-090-02 sums, does not take the max).
 * A moving zone's center is a pure function of the world's current tick
 * (w->tick) and the zone's own start tick and velocity -- no per-tick
 * mutation, no stored "current position" -- so it needs no tick hook from
 * sim.c/unit.c (which fog.c cannot add to; it owns only this file). */
static double om_fog_zone_interference_at(const om_fog_state *st, const om_world *w,
                                           double x, double y, uint32_t layer) {
    uint32_t i;
    double sum = 0.0;
    if (!st) return 0.0;
    for (i = 0; i < st->n_zones; i++) {
        const om_fog_zone *z = &st->zones[i];
        double cx = z->x, cy = z->y, d, frac;
        if (z->layer != layer) continue;
        if (z->moving) {
            uint64_t elapsed = (w->tick >= z->start_tick) ? (w->tick - z->start_tick) : 0;
            cx = z->x + z->vx * (double)elapsed;
            cy = z->y + z->vy * (double)elapsed;
        }
        if (z->radius <= 0.0) continue;
        d = om_fog_dist(x, y, cx, cy);
        if (d >= z->radius) continue;
        frac = 1.0 - d / z->radius;
        sum += z->intensity * frac;
    }
    return om_fog_clamp01(sum);
}

/* Exact cover test. A cover disc blocks the segment when the segment passes
 * through it; a disc that contains an endpoint does not hide that unit (it is
 * standing in it, R-007-06). With ROUTE_AROUND_TERRAIN on, a disc of height h
 * blocks only when the lower of the two unit layers is below h (engine layers
 * 0..h-1, R-007-01, R-007-02). Switch off, any cover blocks on every layer
 * (Q-098-01): the by_height skip is not taken.
 * PP baseline only (switch = 0); deleted with the two movement switches at the end of Phase E (A140)
 * See also: the by_height skip below, the new path.
 * See also: om_combat_can_shoot in tactical_move.c, which must agree. */
static int om_fog_cover_blocks(const om_world *w, double ox, double oy, double tx, double ty, uint32_t low_layer) {
    int by_height = om_tactical_get_param(w, OM_TP_ROUTE_AROUND_TERRAIN) != 0.0;
    uint32_t i, n = om_map_cover_count(w);
    double dx = tx - ox, dy = ty - oy;
    double len2 = dx * dx + dy * dy;
    for (i = 0; i < n; i++) {
        double cx, cy, r, h, t, px, py;
        if (!om_map_cover_at(w, i, &cx, &cy, &r, &h)) continue;
        if (by_height && (double)low_layer >= h) continue; /* new path: cover height in layers, R-007-01 */
        if (om_fog_dist(ox, oy, cx, cy) <= r || om_fog_dist(tx, ty, cx, cy) <= r) continue;
        t = (len2 > 0.0) ? ((cx - ox) * dx + (cy - oy) * dy) / len2 : 0.0;
        if (t < 0.0) t = 0.0;
        if (t > 1.0) t = 1.0;
        px = ox + dx * t;
        py = oy + dy * t;
        if (om_fog_dist(px, py, cx, cy) < r) return 1;
    }
    return 0;
}

/* Defined in tactical_mapgen.c, not in the header: 1 blocked, 0 open, 100 wu cells.
 * See also: om_mapgen_cell_blocked in tactical_mapgen.c. */
extern int om_mapgen_cell_blocked(const om_world *w, uint32_t layer, int32_t cx, int32_t cy);

static int32_t om_fog_cell_floor(double v) {
    int32_t c = (int32_t)(v / OM_NAVMESH_CELL_SIZE);
    if ((double)c * OM_NAVMESH_CELL_SIZE > v) c--;
    return c;
}

static int32_t om_fog_cell_ceil(double v) {
    int32_t c = (int32_t)(v / OM_NAVMESH_CELL_SIZE);
    if ((double)c * OM_NAVMESH_CELL_SIZE < v) c++;
    return c;
}

/* R-098-02 (A159): a blocked route-grid cell on the lower layer of the pair blocks the line when the segment has
 * positive-length overlap with the half-open cell [lo, hi); touching only a corner point does not, and a segment
 * lying along a cell's low edge is inside that cell.
 * Exact walk, column by column: the segment is clipped to each 100 wu column, and the rows its y-span covers
 * are tested. The cells holding the two units are exempt (standing in it, as with cover).
 * Only with ROUTE_AROUND_TERRAIN on. See also: om_combat_can_shoot in tactical_move.c (fire side). */
static int om_fog_grid_blocks(const om_world *w, double ox, double oy, double tx, double ty, uint32_t low_layer) {
    int ground_terrain = om_era_kind(w) == 1 && om_terrain_present(w);
    double dx = tx - ox, dy = ty - oy;
    double xmin = (ox < tx) ? ox : tx, xmax = (ox < tx) ? tx : ox;
    int32_t c0x = om_fog_cell_floor(ox), c0y = om_fog_cell_floor(oy);
    int32_t c1x = om_fog_cell_floor(tx), c1y = om_fog_cell_floor(ty);
    int32_t col, col_lo = om_fog_cell_floor(xmin), col_hi = om_fog_cell_floor(xmax);
    if (om_tactical_get_param(w, OM_TP_ROUTE_AROUND_TERRAIN) == 0.0) return 0;
    for (col = col_lo; col <= col_hi; col++) {
        double left = (double)col * OM_NAVMESH_CELL_SIZE, right = left + OM_NAVMESH_CELL_SIZE;
        double xa = (xmin > left) ? xmin : left, xb = (xmax < right) ? xmax : right;
        double ya, yb, ylo, yhi;
        int32_t row, row_lo, row_hi;
        if (dx == 0.0) {
            ya = oy;
            yb = ty;
        } else {
            if (xa >= xb) continue;
            ya = oy + dy * (xa - ox) / dx;
            yb = oy + dy * (xb - ox) / dx;
        }
        ylo = (ya < yb) ? ya : yb;
        yhi = (ya < yb) ? yb : ya;
        row_lo = om_fog_cell_floor(ylo);
        row_hi = (ylo == yhi) ? row_lo : om_fog_cell_ceil(yhi) - 1;
        for (row = row_lo; row <= row_hi; row++) {
            if ((col == c0x && row == c0y) || (col == c1x && row == c1y)) continue;
            if (ground_terrain &&
                om_terrain_band_at(w, ((double)col + 0.5) * OM_NAVMESH_CELL_SIZE, ((double)row + 0.5) * OM_NAVMESH_CELL_SIZE) - 1 > (int)low_layer)
                continue;
            if (om_mapgen_cell_blocked(w, low_layer, col, row)) return 1;
        }
    }
    return 0;
}

static int om_fog_unit_pos(const om_world *w, uint32_t unit, double *x, double *y) {
    return om_unit_get_pos(w, unit, x, y);
}

static uint32_t om_fog_unit_layer(const om_world *w, uint32_t unit) {
    int32_t l = om_unit_get_layer(w, unit);
    return (l < 0) ? 0u : (uint32_t)l;
}

static int om_fog_elevation(const om_fog_state *st, uint32_t unit_id) {
    const om_fog_unit_track *t = om_fog_find_tracked(st, unit_id);
    return t ? t->elevation_tier : 0;
}

/* Grid candidate radii (om_grid_query_circle / om_grid_iter, csrc/unit.c).
 * A fog effective radius can exceed the sensor radius only through the
 * elevation bonus (cross-layer factors are capped at 1.0, interference only
 * shrinks), so an upper bound is sensor * (1 + bonus * highest tier) with a
 * relative slack that absorbs rounding. Candidates are re-tested exactly by
 * om_unit_can_see, so the bound only has to never be too small. Units are
 * never removed and their ids are dense from 1, so the world-wide maximum
 * sensor radius is extended incrementally over the ids not yet scanned. */
#define OM_FOG_BOUND_SLACK 1e-9

static double om_fog_elev_scale(int max_elev) {
    return (max_elev > 0) ? 1.0 + OM_ELEVATION_SENSOR_BONUS_PER_TIER * (double)max_elev : 1.0;
}

/* Ground era: a flyer is seen from max(radii) x OM_TP_GROUND_FLYER_SEEN_MULT, so candidate bounds widen by that mult
 * (bound only has to never be too small). The elevation bonus is skipped there, so the bound stays an upper bound. */
static double om_fog_ground_reach_w(const om_fog_state *st, const om_world *w) {
    double m = om_tactical_get_param(w, OM_TP_GROUND_FLYER_SEEN_MULT);
    return (st && st->era_kind == 1 && m > 1.0) ? m : 1.0;
}
#define om_fog_ground_reach(st) om_fog_ground_reach_w((st), w)

static double om_fog_world_bound(const om_world *w) {
    om_fog_state *st = om_fog((om_world *)w);
    om_world *mw = (om_world *)w;
    int type;
    while ((type = om_unit_get_unit_type(w, st->bound_scanned + 1)) >= 0) {
        double sr = om_unit_profile_sensor_radius(mw, type);
        if (sr > st->max_sensor) st->max_sensor = sr;
        st->bound_scanned++;
    }
    return st->max_sensor * om_fog_elev_scale(st->max_elev) * om_fog_ground_reach(st) * (1.0 + OM_FOG_BOUND_SLACK);
}

static double om_fog_observer_bound(const om_fog_state *st, const om_world *w, uint32_t observer) {
    int type = om_unit_get_unit_type(w, observer);
    if (type < 0) return 0.0;
    return om_unit_profile_sensor_radius((om_world *)w, type) *
           om_fog_elev_scale(om_fog_elevation(st, observer)) * om_fog_ground_reach_w(st, w) * (1.0 + OM_FOG_BOUND_SLACK);
}

/* ALG-65 effective sensor radius for an observer: base radius by unit type
 * (om_unit_profile_sensor_radius) scaled down by the observer's own
 * interference on the observer's layer (R-089-01, R-090-03: only the
 * observer's position is sampled), then scaled by the elevation-tier bonus
 * when a target tier is given.
 * Q-092-01 (algorithms.md ALG-65): the era-flag gate described in R-091-02 and
 * the unconditional bonus asserted by R-091-03's own fenced numbers ("Settled
 * Reach" with no om_set_era_flag call) do not agree; both fenced tests pass
 * only if the bonus always applies, so it always applies here (the flag is
 * stored by om_set_era_flag but not consulted by this formula). */
static double om_fog_effective_radius_at(const om_fog_state *st, const om_world *w, uint32_t observer, int type,
                                          double ox, double oy, uint32_t layer,
                                          uint32_t target_elev_tier, int have_target_elev) {
    double base, interference, effective;
    if (type < 0) return 0.0;
    base = om_unit_profile_sensor_radius((om_world *)w, type);
    interference = om_fog_zone_interference_at(st, w, ox, oy, layer);
    effective = base * (1.0 - interference);
    if (have_target_elev && !(st && st->era_kind == 1)) {
        double mult = 1.0 + OM_ELEVATION_SENSOR_BONUS_PER_TIER *
                      (double)(om_fog_elevation(st, observer) - (int)target_elev_tier);
        effective *= (mult > 0.0) ? mult : 0.0;
    }
    return effective;
}

static double om_fog_effective_radius(const om_fog_state *st, const om_world *w, uint32_t observer,
                                       uint32_t target_elev_tier, int have_target_elev) {
    int type = om_unit_get_unit_type(w, observer);
    double ox, oy;
    if (type < 0 || !om_fog_unit_pos(w, observer, &ox, &oy)) return 0.0;
    return om_fog_effective_radius_at(st, w, observer, type, ox, oy, om_fog_unit_layer(w, observer),
                                      target_elev_tier, have_target_elev);
}

static int om_fog_ping_reveals(const om_world *w, int32_t faction, uint32_t unit);

static int om_fog_can_see_at(const om_world *w, uint32_t observer, double ox, double oy, uint32_t ol,
                             uint32_t target, double tx, double ty, uint32_t tl);

/* Candidate observers come from the grid around the target; an any-of, so the iterator's order does not matter.
 * A live G7 ping disc of the faction joins its visible set (R-162-05). */
int om_fog_faction_sees(const om_world *w, int32_t faction, uint32_t target) {
    om_grid_iter it;
    double tx, ty;
    uint32_t observer, tl;
    if (!om_fog_unit_pos(w, target, &tx, &ty)) return 0;
    if (om_unit_get_faction(w, target) >= 0) {
        tl = om_fog_unit_layer(w, target);
        om_grid_iter_begin_faction(&it, (om_world *)w, faction, tx, ty, om_fog_world_bound(w));
        while ((observer = om_grid_iter_next(&it)) != 0) {
            double ox, oy;
            if (!om_unit_alive((om_world *)w, observer) || !om_fog_unit_pos(w, observer, &ox, &oy)) continue;
            if (om_fog_can_see_at(w, observer, ox, oy, om_fog_unit_layer(w, observer), target, tx, ty, tl)) return 1;
        }
    }
    return om_fog_ping_reveals(w, faction, target);
}

